package template

import (
	"bufio"
	"math"
	"os"
	"strconv"
	"strings"
	"testing"
)

// The format-spec mini-language and str() of a float, against Python's own
// answers: testdata/pyformat, generated by tools/make-pyformat-corpus.py
// with Python 3.12.3. A refusal is an answer too: where Python raises,
// halite must fail rather than render something (issue 321, M-52).

func readTSV(t *testing.T, name string, fields int) [][]string {
	t.Helper()
	f, err := os.Open("testdata/pyformat/" + name)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	var rows [][]string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		row := strings.SplitN(sc.Text(), "\t", fields)
		if len(row) != fields {
			t.Fatalf("%s: a line with %d fields: %q", name, len(row), sc.Text())
		}
		rows = append(rows, row)
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	return rows
}

func TestPyFormatSpecMatchesPython(t *testing.T) {
	rows := readTSV(t, "format.tsv", 4)
	bad := 0
	for _, r := range rows {
		kind, raw, spec, want := r[0], r[1], r[2], r[3]
		var v any
		switch kind {
		case "s":
			v = raw
		case "b":
			v = raw == "True"
		case "i":
			n, err := strconv.ParseInt(raw, 10, 64)
			if err != nil {
				t.Fatalf("int %q: %v", raw, err)
			}
			v = n
		case "f":
			x, err := strconv.ParseFloat(raw, 64)
			if err != nil {
				t.Fatalf("float %q: %v", raw, err)
			}
			v = x
		}
		got, err := pyFormatValue(v, spec)
		switch {
		case strings.HasPrefix(want, "!"):
			if err == nil {
				bad++
				t.Errorf("format(%s %s, %q) = %q; Python raises %s", kind, raw, spec, got, want[1:])
			}
		case err != nil || got != want:
			bad++
			t.Errorf("format(%s %s, %q) = %q, %v; Python gives %q", kind, raw, spec, got, err, want)
		}
		if bad > 20 {
			t.Fatal("too many differences")
		}
	}
	if len(rows) < 3000 {
		t.Fatalf("only %d cases were read", len(rows))
	}
}

func TestFloatRendersAsPythonStr(t *testing.T) {
	rows := readTSV(t, "str.tsv", 2)
	for _, r := range rows {
		x, err := strconv.ParseFloat(r[0], 64)
		if err != nil {
			t.Fatalf("float %q: %v", r[0], err)
		}
		if got := pyFloatStr(x); got != r[1] {
			t.Errorf("str(%s) = %s; Python gives %s", r[0], got, r[1])
		}
	}
	if len(rows) < 1000 {
		t.Fatalf("only %d cases were read", len(rows))
	}
}

// Through the method a template calls, the examples 5.359 named.
func TestStrFormatAppliesTheSpec(t *testing.T) {
	for _, c := range []struct{ src, want string }{
		{`{{ "{:>5}".format("a") }}`, "    a"},
		{`{{ "{:.2f}".format(3.14159) }}`, "3.14"},
		{`{{ "{:,}".format(1234567) }}`, "1,234,567"},
		{`{{ "{0:08.3f}|{1:<4}|{x:^7}".format(2.5, "ab", x="mid") }}`, "0002.500|ab  |  mid  "},
	} {
		if got := render(t, c.src, nil); got != c.want {
			t.Errorf("%s -> %q, jinja2 3.1.2 gives %q", c.src, got, c.want)
		}
	}
	mustContain(t, renderErr(t, `{{ "{:d}".format("a") }}`, nil).Error(), "format")
}

// **A float renders as Python's str() writes it** (issue 321, M-52).
// Rendering was fixed point below 1e15 and Go's 'g' above, so 1e15 came
// out "1e+15" and an infinity "+Inf". Captured from jinja2 3.1.2.
func TestFloatRendersAsJinjaDoes(t *testing.T) {
	inf := map[string]any{"pinf": math.Inf(1), "ninf": math.Inf(-1), "nan": math.NaN()}
	for _, c := range []struct{ src, want string }{
		{`{{ 1e15 }}`, "1000000000000000.0"},
		{`{{ 1e16 }}`, "1e+16"},
		{`{{ 1e-5 }}`, "1e-05"},
		{`{{ 0.0001 }}`, "0.0001"},
		{`{{ -0.0 }}`, "-0.0"},
		{`{{ pinf }}|{{ ninf }}|{{ nan }}`, "inf|-inf|nan"},
	} {
		if got := render(t, c.src, inf); got != c.want {
			t.Errorf("%s -> %q, jinja2 3.1.2 gives %q", c.src, got, c.want)
		}
	}
}

func decodePyArg(t *testing.T, enc string) any {
	t.Helper()
	kind, raw, ok := strings.Cut(enc, ":")
	if !ok {
		t.Fatalf("argument %q", enc)
	}
	switch kind {
	case "s":
		return raw
	case "b":
		return raw == "True"
	case "n":
		return nil
	case "i":
		n, err := strconv.ParseInt(raw, 10, 64)
		if err != nil {
			t.Fatalf("int %q: %v", raw, err)
		}
		return n
	case "f":
		x, err := strconv.ParseFloat(raw, 64)
		if err != nil {
			t.Fatalf("float %q: %v", raw, err)
		}
		return x
	}
	t.Fatalf("argument kind %q", kind)
	return nil
}

func TestPercentFormatMatchesPython(t *testing.T) {
	rows := readTSV(t, "percent.tsv", 3)
	bad := 0
	for _, r := range rows {
		format, argtext, want := r[0], r[1], r[2]
		var args []any
		kwargs := map[string]any{}
		if argtext != "" {
			for _, a := range strings.Split(argtext, "\x1f") {
				if k, v, ok := strings.Cut(a, "="); ok && !strings.Contains(k, ":") {
					kwargs[k] = decodePyArg(t, v)
					continue
				}
				args = append(args, decodePyArg(t, a))
			}
		}
		got, err := pyPercent(format, args, kwargs)
		switch {
		case strings.HasPrefix(want, "!"):
			if err == nil {
				bad++
				t.Errorf("%q %% %q = %q; Python raises %s", format, argtext, got, want[1:])
			}
		case err != nil || got != want:
			bad++
			t.Errorf("%q %% %q = %q, %v; Python gives %q", format, argtext, got, err, want)
		}
		if bad > 25 {
			t.Fatal("too many differences")
		}
	}
	if len(rows) < 3000 {
		t.Fatalf("only %d cases were read", len(rows))
	}
}

// **The format filter is Python's `%`**, through the filter a template
// calls (issue 321, M-52). It was fmt.Sprintf: `%s` of a bool, `%r` and
// `%(name)s` failed, `%g` printed Go's shortest digits, `%d` of a float
// failed and `%x` of a string printed its bytes. Captured from jinja2
// 3.1.2; an empty want is an error there.
func TestFormatFilterIsPythonPercent(t *testing.T) {
	for _, c := range []struct{ src, want string }{
		{`{{ "%s" | format(true) }}`, "True"},
		{`{{ "%r" | format("a") }}`, "'a'"},
		{`{{ "%(x)s-%(y)d" | format(x="a", y=2) }}`, "a-2"},
		{`{{ "%g" | format(1/3) }}`, "0.333333"},
		{`{{ "%d" | format(2.9) }}`, "2"},
		{`{{ "%5.1f|%-4s|%03d" | format(3.14159, "ab", 7) }}`, "  3.1|ab  |007"},
		{`{{ "%s" | format(none) }}`, "None"},
		{`{{ "%s" | format([1, 2]) }}`, "[1, 2]"},
		{`{{ "%x" | format("a") }}`, ""},
		{`{{ "%s %s" | format("a") }}`, ""},
	} {
		res, err := NewEnvironment(nil, DefaultOptions()).RenderString(c.src, "t.sls", nil)
		if c.want == "" {
			if err == nil {
				t.Errorf("%s -> %q, jinja2 3.1.2 fails it", c.src, res.Output)
			}
			continue
		}
		if err != nil || res.Output != c.want {
			var got string
			if err == nil {
				got = res.Output
			}
			t.Errorf("%s -> %q, %v; jinja2 3.1.2 gives %q", c.src, got, err, c.want)
		}
	}
}
